START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE TABLE "EntriesDigestRuns" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RunDate" character varying(10) NOT NULL,
        "ClaimedAt" timestamp with time zone NOT NULL,
        "Status" integer NOT NULL,
        "Manual" boolean NOT NULL,
        "Competitions" integer NOT NULL,
        "Total" integer NOT NULL,
        "CompletedAt" timestamp with time zone,
        CONSTRAINT "PK_EntriesDigestRuns" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE TABLE "EntriesDigestCompetitions" (
        "CompetitionId" integer NOT NULL,
        "RunId" integer NOT NULL,
        CONSTRAINT "PK_EntriesDigestCompetitions" PRIMARY KEY ("CompetitionId"),
        CONSTRAINT "FK_EntriesDigestCompetitions_EntriesDigestRuns_RunId" FOREIGN KEY ("RunId") REFERENCES "EntriesDigestRuns" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE TABLE "EntriesDigestRecipients" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "RunId" integer NOT NULL,
        "OptInId" integer NOT NULL,
        "Status" integer NOT NULL,
        "ClaimedAt" timestamp with time zone,
        "ClaimToken" uuid,
        "Attempts" integer NOT NULL,
        CONSTRAINT "PK_EntriesDigestRecipients" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_EntriesDigestRecipients_EntriesDigestRuns_RunId" FOREIGN KEY ("RunId") REFERENCES "EntriesDigestRuns" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE INDEX "IX_EntriesDigestCompetitions_RunId" ON "EntriesDigestCompetitions" ("RunId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE UNIQUE INDEX "IX_EntriesDigestRecipients_RunId_OptInId" ON "EntriesDigestRecipients" ("RunId", "OptInId");
    END IF;
