DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE INDEX "IX_EntriesDigestRecipients_RunId_Status" ON "EntriesDigestRecipients" ("RunId", "Status");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
    CREATE UNIQUE INDEX "IX_EntriesDigestRuns_RunDate" ON "EntriesDigestRuns" ("RunDate");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027161822_AddEntriesDigest') THEN
